const places=[
 {id:'liberdade',title:'Uma pausa na Liberdade',category:'Sabores',area:'Liberdade',short:'Uma vitrine, um aroma, um convite para conhecer outra história.',text:'Na Liberdade, a paisagem também abre o apetite. Lanternas, vitrines e conversas dividem a mesma rua, enquanto cada escolha de comida oferece uma maneira de conhecer a cidade. Em vez de procurar uma única identidade para São Paulo, esta camada convida a perceber os encontros. Que sabor faria você voltar?',symbol:'◒',bg:'#dfba96',fg:'#7f402b'},
 {id:'feira',title:'Domingo tem feira',category:'Sabores',area:'Uma feira do seu bairro',short:'Entre a conversa da banca e a primeira mordida no pastel.',text:'O pastel chega quente, a conversa continua e o passeio ganha uma pausa. Nesta camada, a comida é uma porta de entrada para os pequenos rituais da cidade: escolher uma banca, dividir uma porção, voltar pelo mesmo caminho. A fotografia representa o pastel de feira, sem apontar uma barraca específica. Qual é o seu ritual de domingo?',symbol:'◐',bg:'#e0c75e',fg:'#7b4629'},
 {id:'beco',title:'A rua como tela',category:'Arte de Rua',area:'Vila Madalena · Beco do Batman',short:'Quando as paredes convidam a olhar mais uma vez.',text:'Aqui, a rua pede um olhar mais demorado. No Beco do Batman, cores e formas ocupam as paredes e transformam o passeio em uma conversa com a arte. A fotografia registra um momento dessa paisagem, que pode mudar com o tempo. Escolha um detalhe e imagine a história que ele contaria.',symbol:'✳',bg:'#b8b9d2',fg:'#514785'},
 {id:'minhocao',title:'Outros olhos para o concreto',category:'Arte de Rua',area:'Região do Minhocão',short:'Cor e escala mudam o jeito de perceber uma fachada.',text:'O concreto parece diferente quando a cor entra em cena. Este registro da região do Minhocão aproxima a arte da paisagem cotidiana: fachadas, janelas e superfícies passam a disputar a atenção. O convite é simples: olhar para cima, procurar um contraste e descobrir algo que a pressa costuma esconder.',symbol:'▥',bg:'#c2c8b5',fg:'#52694c'},
 {id:'ibirapuera',title:'Um intervalo no Ibirapuera',category:'Respiros',area:'Parque Ibirapuera',short:'A cidade segue lá fora. Aqui, o olhar desacelera.',text:'Uma sequência de árvores muda o ritmo do olhar. No Ibirapuera, esta fotografia convida a imaginar um intervalo entre dois compromissos: alguns passos, uma sombra, uma conversa sem relógio. A camada verde também faz parte de São Paulo. Que lembrança você gostaria de guardar de uma pausa assim?',symbol:'❋',bg:'#b7c6ab',fg:'#34583d'},
 {id:'cantareira',title:'O verde no horizonte',category:'Respiros',area:'Serra da Cantareira',short:'Uma camada de natureza para ampliar o horizonte.',text:'A fotografia do Núcleo Pedra Grande, na Cantareira, troca a escala dos prédios pela dos pequenos encontros com a natureza. A água, as árvores e as aves convidam a observar antes de seguir. Esta é uma seleção afetiva da paisagem; consulte os canais oficiais para planejar uma visita. O que você percebe quando desacelera?',symbol:'△',bg:'#aabeb5',fg:'#3d6656'}
,{"id":"mercado","category":"Sabores","title":"Cores e sabores do Mercadão","area":"Mercado Municipal de São Paulo","short":"Uma banca inteira de possibilidades para o próximo encontro.","text":"Frascos, frutas secas e ingredientes fazem da banca uma pequena paisagem. No Mercado Municipal, olhar também é uma forma de descobrir sabores. A foto registra um momento desse comércio; os produtos e preços retratados não são uma oferta atual. Que ingrediente você levaria para uma mesa de encontros?","symbol":"◒","bg":"#c3c7b5","fg":"#3d594b"},
{"id":"paulista","category":"Cidade & Memória","title":"Um olhar vertical na Paulista","area":"Avenida Paulista","short":"Entre fachadas e movimento, a cidade convida a olhar para cima.","text":"As linhas do edifício recortam o céu, enquanto a vida continua perto da calçada. A Paulista desta fotografia é feita de contraste: altura e passo, janelas e conversas, ritmo e pausa. Experimente escolher uma forma na fachada e procurá-la de novo ao redor. O que a arquitetura faz você sentir?","symbol":"⌂","bg":"#c3c7b5","fg":"#3d594b"},
{"id":"copan","category":"Cidade & Memória","title":"Curvas que guardam histórias","area":"Edifício Copan · Centro","short":"Uma curva muda a maneira de reconhecer o horizonte.","text":"O Copan entra na paisagem como uma linha que se recusa a ser reta. Na fotografia, suas curvas encontram outros prédios e deixam imaginar as muitas vidas por trás das janelas. Esta camada olha para a arquitetura como memória cotidiana, feita também de pequenos gestos. Que detalhe você escolheria guardar?","symbol":"⌂","bg":"#c3c7b5","fg":"#3d594b"},
{"id":"masp","category":"Cidade & Memória","title":"Um encontro sob o vermelho","area":"MASP · Avenida Paulista","short":"Arte, arquitetura e o espaço entre um compromisso e outro.","text":"O vermelho chama o olhar; o espaço sob o edifício abre uma pausa. Nesta imagem do MASP, a arquitetura faz parte da experiência de estar na cidade, mesmo antes de entrar em uma exposição. O convite é perceber o que um lugar oferece a quem passa: sombra, escala, encontro. Como seria seu cartão desse instante?","symbol":"⌂","bg":"#c3c7b5","fg":"#3d594b"},
{"id":"botanico","category":"Respiros","title":"Um banco para desacelerar","area":"Jardim Botânico de São Paulo","short":"Uma cobertura, alguns bancos e tempo para olhar o verde.","text":"O caminho coberto organiza a paisagem em linhas, sombras e intervalos. No Jardim Botânico desta fotografia, os bancos parecem fazer uma pergunta simples: e se você ficasse um pouco? Esta camada é um convite à observação, não um roteiro de visita. Para planejar um passeio, confira as condições nos canais oficiais.","symbol":"❋","bg":"#c3c7b5","fg":"#3d594b"},
{"id":"luz","category":"Respiros","title":"O tempo toca no Jardim da Luz","area":"Jardim da Luz","short":"Entre árvores e música, uma outra velocidade para a cidade.","text":"Dois músicos dividem o banco e a cena com as árvores. Esta fotografia do Jardim da Luz guarda um instante em que o encontro ocupa mais espaço do que a pressa. Não sabemos que canção estava sendo tocada; podemos imaginar o lugar que a música abre na memória. Qual seria a trilha sonora da sua São Paulo?","symbol":"❋","bg":"#c3c7b5","fg":"#3d594b"}
,{"id":"pizzapaulista","category":"Sabores","title":"Uma pizza, dois encontros","area":"Vila Mariana · São Paulo","short":"Do salgado ao doce, uma mesa para dividir.","text":"A fotografia reúne duas metades na mesma caixa: tomate e queijo de um lado, chocolate do outro. O encontro de sabores convida a pensar nas combinações que fazem parte da vida em São Paulo. Mais do que uma escolha de cobertura, esta camada celebra o gesto de repartir. Qual metade você escolheria primeiro?","symbol":"◒","bg":"#c2c8b5","fg":"#34583d"},
{"id":"pizzadoce","category":"Sabores","title":"Uma fatia doce da Mooca","area":"Mooca · São Paulo","short":"Chocolate, amêndoas e uma pausa à mesa.","text":"Uma pizza quadrada coberta de chocolate e amêndoas transforma a sobremesa em paisagem. O registro foi feito na Mooca e traz outro jeito de olhar para um alimento que aceita tantas interpretações. Imagine as conversas ao redor dessa tábua e escolha um detalhe para levar no cartão.","symbol":"◒","bg":"#c2c8b5","fg":"#34583d"},
{"id":"becocores","category":"Arte de Rua","title":"Mais uma esquina de cor","area":"Beco do Batman · Vila Madalena","short":"Portões, paredes e desenhos dividem a paisagem.","text":"Nesta outra vista do Beco do Batman, a arte acompanha portões, muros e passagens. Amarelo, vermelho e figuras pintadas criam várias rotas para o olhar. O registro guarda um instante de uma paisagem que muda. Qual detalhe você descobriria depois de olhar pela segunda vez?","symbol":"✳","bg":"#c2c8b5","fg":"#34583d"},
{"id":"kobra","category":"Arte de Rua","title":"Um rosto entre as árvores","area":"Mural de Eduardo Kobra · Avenida Paulista","short":"A cor sobe pela fachada e encontra o céu.","text":"Na fotografia, um mural de Eduardo Kobra surge entre árvores, edifícios e o movimento da Paulista. Os fragmentos de cor fazem o olhar alternar entre o retrato e a cidade ao redor. Esta camada convida a perceber como uma obra muda a maneira de reconhecer uma rua.","symbol":"✳","bg":"#c2c8b5","fg":"#34583d"},
{"id":"parqueaugusta","category":"Respiros","title":"O verde também guarda memória","area":"Parque Augusta · registro de 2017","short":"Um registro de árvores e espaço aberto no centro.","text":"A imagem de 2017 guarda um momento do espaço do Parque Augusta. Árvores, gramado e prédios próximos aproximam duas escalas da cidade. A fotografia é um registro histórico, não uma descrição das condições atuais. Que mudanças e permanências você procuraria ao comparar lembranças de um lugar?","symbol":"❋","bg":"#c2c8b5","fg":"#34583d"},
{"id":"burlemarx","category":"Respiros","title":"Entre o rio e a copa das árvores","area":"Parque Burle Marx · São Paulo","short":"Uma vista ampla para perceber o verde na cidade.","text":"Nesta vista do Parque Burle Marx, as copas das árvores encontram construções, vias e o rio ao fundo. O verde aparece dentro de uma paisagem urbana maior, cheia de camadas. A pausa aqui é visual: seguir uma linha de árvores e perceber onde ela encontra o horizonte.","symbol":"❋","bg":"#c2c8b5","fg":"#34583d"},
{"id":"pinacoteca","category":"Cidade & Memória","title":"Tijolos que convidam a entrar","area":"Pinacoteca · Luz","short":"Uma fachada para olhar de perto.","text":"A fotografia aproxima o olhar dos tijolos, colunas e detalhes da fachada da Pinacoteca. Antes de qualquer exposição, o próprio edifício já propõe uma descoberta. Esta camada celebra a curiosidade de observar a cidade em diferentes escalas: do conjunto ao pequeno detalhe.","symbol":"⌂","bg":"#c2c8b5","fg":"#34583d"},
{"id":"estacaoluz","category":"Cidade & Memória","title":"Linhas que se encontram na Luz","area":"Estação da Luz · São Paulo","short":"Trilhos, estrutura e luz em preto e branco.","text":"A cobertura da estação desenha um caminho para o olhar. Em preto e branco, trilhos e estruturas deixam imaginar chegadas, partidas e esperas. A fotografia guarda um instante, enquanto a memória completa o movimento. Qual encontro você colocaria entre essas linhas?","symbol":"⌂","bg":"#c2c8b5","fg":"#34583d"}
];
const chosen=new Set();let filter='Todas';const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function asset(p,w=720){return PLACE_IDS.includes(p.id)?preparedMedia[p.id].card:''}
function render(){ $('#cards').innerHTML=places.filter(p=>filter==='Todas'||p.category===filter).map((p)=>`<article class="card"><div class="card-art" data-place="${p.id}" data-number="${String(places.indexOf(p)+1).padStart(2,'0')}">${asset(p)?`<img loading="lazy" src="${esc(asset(p))}" alt="${esc(t(p.title))}">`:`<span class="art-lines"></span><span class="art-symbol" aria-hidden="true">${p.symbol}</span>`}<span class="tag">${t(p.category)}</span><button class="pick" data-id="${p.id}" aria-label="${chosen.has(p.id)?t('Remover'):t('Guardar')} ${t(p.title)}" aria-pressed="${chosen.has(p.id)}">${chosen.has(p.id)?'✓':'+'}</button></div><h3>${t(p.title)}</h3><p>${t(p.short)}</p><button class="story-link" data-story="${p.id}">${t("Conhecer a história ↗")}</button></article>`).join('');$('#count').textContent=chosen.size+'/3';$('#selected').textContent=chosen.size?[...chosen].map(id=>t(places.find(p=>p.id===id).title)).join(' · '):t('Seus lugares favoritos aparecem aqui.');$('#preview-places').innerHTML=chosen.size?[...chosen].map(id=>esc(t(places.find(p=>p.id===id).title))).join('<br>'):t('Sua cidade.<br>Seu jeito de olhar.');$('#download').disabled=chosen.size!==3;$('#download').textContent=chosen.size===3?t('Baixar meu cartão-postal ↓'):t('Escolha 3 lugares para criar');}
function toggle(id){if(!PLACE_IDS.includes(id))return;if(chosen.has(id))chosen.delete(id);else if(chosen.size<3)chosen.add(id);else {$('#status').textContent=t('Seu cartão já tem três lugares. Remova um para trocar.');return}$('#status').textContent='';render()}
$('#cards').addEventListener('click',e=>{const pick=e.target.closest('[data-id]');if(pick)toggle(pick.dataset.id);const story=e.target.closest('[data-story]');if(story){const p=places.find(p=>p.id===story.dataset.story);$('#story-category').textContent=t(p.category);$('#story-title').textContent=t(p.title);$('#story-text').textContent=t(p.text);$('#story-location').textContent=t(p.area);$('#story-add').textContent=chosen.has(p.id)?t('Remover do meu cartão'):t('Guardar no meu cartão');$('#story-add').onclick=()=>{toggle(p.id);$('#story').close()};$('#story').showModal()}});$('.close').onclick=()=>$('#story').close();$('.filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(!b)return;filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));render()};$('#message').oninput=()=>{const input=$('#message');input.value=cleanMessage(input.value);$('#preview-message').textContent=input.value;document.dispatchEvent(new Event('messagechange'))};
function wrap(ctx,text,x,y,max,line){let row='';for(const word of text.split(' ')){if(ctx.measureText(row+word).width>max&&row){ctx.fillText(row.trim(),x,y);y+=line;row=''}row+=word+' '}ctx.fillText(row.trim(),x,y);return y+line}
render();



$("#photo-credits").innerHTML=Object.entries(photoCredits).map(([id,c])=>`<p><strong>${esc(t(places.find(p=>p.id===id).title))}</strong> — ${esc(c.author)} · <a href="${esc(c.licenseUrl)}" target="_blank" rel="noopener">${esc(c.license)}</a> · <a href="${esc(c.source)}" target="_blank" rel="noopener">Fonte original</a>. Recorte e redimensionamento na interface.</p>`).join("");


function refreshLocalizedFields(){$('#photo-credits').innerHTML=Object.entries(photoCredits).map(([id,c])=>`<p><strong>${esc(t(places.find(p=>p.id===id).title))}</strong> — ${esc(c.author)} · <a href="${esc(c.licenseUrl)}" target="_blank" rel="noopener noreferrer">${esc(c.license)}</a> · <a href="${esc(c.source)}" target="_blank" rel="noopener noreferrer">${t('Fonte original')}</a>. ${t('Recorte e redimensionamento na interface.')} ${t('Adaptações')}: ${esc(c.license)}.</p>`).join('')}refreshLocalizedFields();
